const AppFormFieldsGetCalcFieldFormSchema = z
  .object({
    noLabel: z.boolean().exactOptional(),
    unit: z.string().max(128).exactOptional(),
    expression: z.string().exactOptional(),
    code: z.string().min(1).max(128).exactOptional(),
    format: z
      .enum([
        'NUMBER',
        'NUMBER_DIGIT',
        'DATETIME',
        'DATE',
        'TIME',
        'HOUR_MINUTE',
        'DAY_HOUR_MINUTE',
      ])
      .exactOptional(),
    unitPosition: z.enum(['BEFORE', 'AFTER']).exactOptional(),
    label: z.string().min(1).max(128).exactOptional(),
    type: z.enum([
      'CALC',
      'CATEGORY',
      'CHECK_BOX',
      'CREATED_TIME',
      'CREATOR',
      'DATE',
      'DATETIME',
      'DROP_DOWN',
      'FILE',
      'GROUP',
      'GROUP_SELECT',
      'LINK',
      'MODIFIER',
      'MULTI_LINE_TEXT',
      'MULTI_SELECT',
      'NUMBER',
      'ORGANIZATION_SELECT',
      'RADIO_BUTTON',
      'RECORD_NUMBER',
      'REFERENCE_TABLE',
      'RICH_TEXT',
      'SINGLE_LINE_TEXT',
      'STATUS',
      'STATUS_ASSIGNEE',
      'SUBTABLE',
      'TIME',
      'UPDATED_TIME',
      'USER_SELECT',
    ]),
    displayScale: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({ type: 'integer', format: 'int64' }),
    hideExpression: z.boolean().exactOptional(),
    required: z.boolean().exactOptional(),
  })
  .openapi({ required: ['type'] })
  .openapi('AppFormFieldsGetCalcFieldForm')

