const AppAclPutRightSchema = z
  .object({
    recordImportable: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'The file import permission of the entity.\nThe record add permissions must also be enabled to set this value as `true`.\n- `true`: Files will be importable\n- `false`: Files will not be importable\nIf ignored, this value is false.',
      }),
    appEditable: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          "The App management permission of the entity.\n- The App's settings will be accessible.\n- The App's settings will not be accessible.\nIf ignored, this value is false.",
      }),
    recordExportable: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'The file export permission of the entity.\n- `true`: Files will be exportable\n- `false`: Files will not be exportable\nIf ignored, this value is false.',
      }),
    recordAddable: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'The record add permission of the entity\n- `true`: Records can be added.\n- `false`: Records cannot be added.\nIf ignored, this value is false.',
      }),
    recordViewable: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'The record view permission of the entity.\n- `true`: Records will be viewable.\n- `false`: Records will not be viewable.\nIf ignored, this value is false.',
      }),
    recordEditable: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'The record edit permission of the entity.\nThe record view permissions must also be enabled to set this value as `true`.\n- `true`: Records will be editable.\n- `false`: Records will not be editable.\nIf ignored, this value is false.',
      }),
    recordDeletable: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'The record delete permission of the entity.\nThe record view permissions must also be enabled to set this value as `true`.\n- `true`: Records will be deletable.\n- `false`: Records will not be deletable.\nIf ignored, this value is false.',
      }),
    includeSubs: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'The permission inheritance settings of the department the permission is granted to. This parameter is available if "ORGANIZATION" is specified for the **rights[].entity.type** parameter.\n- `true`: Permissions will be inherited.\n- `false`: Permissions will not be inherited.\nIf ignored, this value is false.',
      }),
    entity: z
      .object({
        code: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'The code of the entity the permission is granted to.\nTo specify guest space users, add the string "guest/" before the guest\'s log in name.\nIf the "Everyone" group is not specified, the "Everyone" group will have no permissions to view/edit/delete.\nIf "CREATOR" is specified for the **rights[].entity.type** parameter, ignore this parameter. Otherwise, this parameter is required.',
          }),
        type: z
          .enum(['USER', 'ORGANIZATION', 'GROUP', 'CREATOR'])
          .openapi({
            description:
              'The type of the entity the permission will be granted to.\n- **USER**: User\n- **GROUP**: Group\n- **ORGANIZATION**: Department\n- **CREATOR**: The creator of the App',
          }),
      })
      .openapi({
        required: ['type'],
        description: 'An object containing data of the entity the permission is granted to.',
      }),
  })
  .openapi({ required: ['entity'] })
  .openapi('AppAclPutRight')

