export const getKV1AppsJsonRoute = createRoute({
  method: 'get',
  path: '/k/v1/apps.json',
  tags: ['APPS'],
  summary: 'Get apps',
  description:
    'Gets general information of multiple Apps, including the name, description, related Space, creator and updater information.',
  operationId: 'getApps',
  request: {
    query: z.object({
      codes: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'codes',
            in: 'query',
            schema: { items: { type: 'string' }, type: 'array' },
            description:
              'The App Code.\nUp to 100 App Codes can be specified.\nEach App Code must be between 1 to 64 characters. An exact match search will be used, and will be case sensitive.\nIf `null` or an empty array is specified, this parameter will be ignored.',
            required: false,
          },
        }),
      offset: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            name: 'offset',
            in: 'query',
            schema: { type: 'integer', format: 'int64' },
            description:
              'The number of retrievals that will be skipped.\nMust be between 0 and 2,147,483,647. If nothing is specified, it will default to 0.',
            required: false,
          },
        }),
      name: z
        .string()
        .max(64)
        .exactOptional()
        .openapi({
          param: {
            name: 'name',
            in: 'query',
            schema: { maxLength: 64, type: 'string' },
            description:
              "The App Name or a part of it.\nEach App Name must be specified within 64 characters.\nA partial search will be used, and the search will be case insensitive.\nThe localized name of the App in the user's locale will also be included in the search.\nIf `null` or an empty array is specified, this parameter will be ignored.",
            required: false,
          },
        }),
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            schema: { type: 'integer', format: 'int64' },
            description:
              'The number of Apps to retrieve.\nMust be between 1 and 100.\nIf nothing is specified, it will default to 100.',
            required: false,
          },
        }),
      ids: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'ids',
            in: 'query',
            schema: { items: { format: 'long', type: 'string' }, type: 'array' },
            description:
              'The App IDs.\nIntegers from 1 to 9,223,372,036,854,775,807 can be specified.\nUp to 100 IDs can be specified.\nIf `null` or an empty array is specified, this parameter will be ignored.',
            required: false,
          },
        }),
      spaceIds: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'spaceIds',
            in: 'query',
            schema: { items: { format: 'long', type: 'string' }, type: 'array' },
            description:
              'The Space ID of where the App resides in.\nIntegers from 1 to 9,223,372,036,854,775,807 can be specified.\nUp to 100 IDs can be specified.\nIf `null` or an empty array is specified, this parameter will be ignored.',
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'success case of apps/get',
      content: {
        'application/json': {
          schema: z
            .object({ apps: z.array(AppsGetAppWithSpaceIdFormSchema) })
            .openapi({ required: ['apps'] }),
        },
      },
    },
    '4XX': ErrorResponse,
  },
  security: [{ passwordAuth: [] }, { oauth2: ['k:app_settings:read'] }],
})

