export const postKV1RecordsCursorJsonRoute = createRoute({
  method: 'post',
  path: '/k/v1/records/cursor.json',
  tags: ['RECORDS'],
  summary: 'Post records cursor',
  description: 'Adds a cursor so that large amount of records can be obtained from an App.',
  operationId: 'postRecordsCursor',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              app: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .openapi({ type: 'integer', format: 'int64', description: 'The App ID.' }),
              size: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .exactOptional()
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  description:
                    'The maximum number of records the Get Cursor API can retrieve from this cursor with one request.\nThe maximum number is 500 records. If ignored, the default number of records to be retrieved is 100.\nTo retrieve all records, repeatedly call the Get Cursor API.\nFor more information, refer to the following article:\n[Get Cursor](https://kintone.dev/en/docs/kintone/rest-api/records/get-cursor/)',
                }),
              query: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "The search condition for the records the cursor will walk over, written in Kintone's own query syntax.\nThe operators and functions are the same as for the `query` parameter of `GET /k/v1/records.json` — see that parameter for the table of operators each field type allows.\n\n**`order by`, `limit` and `offset` cannot be used here.** The cursor manages paging itself: set the batch size with the `size` parameter, then call `GET /k/v1/records/cursor.json` repeatedly until it reports `next: false`.\n\nIgnoring this parameter creates a cursor over all records that the credential can access.",
                }),
              fields: z
                .array(z.string())
                .exactOptional()
                .openapi({
                  description:
                    'The field codes to be included in the response when using the Get Cursor API. For more information, refer to the following document:\n[Get Cursor](https://kintone.dev/en/docs/kintone/rest-api/records/get-cursor/)\nIf ignored, all accessible fields in the app will be returned.',
                }),
            })
            .openapi({ required: ['app'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'success case of records/cursor/post',
      content: {
        'application/json': {
          schema: z
            .object({ id: z.string(), totalCount: z.string().nullable() })
            .openapi({ required: ['id', 'totalCount'] }),
        },
      },
    },
    '4XX': ErrorResponse,
  },
  security: [{ apiToken: [] }, { passwordAuth: [] }],
})

