export const getKV1SpaceMembersJsonRoute = createRoute({
  method: 'get',
  path: '/k/v1/space/members.json',
  tags: ['SPACES'],
  summary: 'Get space members',
  description: 'Gets the list of Space Members of a Space.',
  operationId: 'getSpaceMembers',
  request: {
    query: z.object({
      id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            name: 'id',
            in: 'query',
            schema: { type: 'integer', format: 'int64' },
            required: true,
            description: 'The Space ID.',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'success case of space/members/get',
      content: {
        'application/json': {
          schema: z
            .object({
              members: z
                .array(
                  z.union([
                    SpaceMembersGetUserBeanSchema,
                    SpaceMembersGetOrganizationBeanSchema,
                    SpaceMembersGetGroupBeanSchema,
                  ]),
                )
                .exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
    '4XX': ErrorResponse,
  },
  security: [{ passwordAuth: [] }],
})

